    "type_prefix": "Typ ",
    "polarity_desc_A": "Straight-Through-Kabel. Key-up an Ende A, Key-down an Ende B. Der gedrehte Stecker an Ende B kehrt die Faserreihe um — Position n an Ende A landet an Position (total+1−n) an Ende B.",
    "polarity_desc_B": "Umgekehrtes Kabel (Key-up zu Key-up). Faserposition n an Ende A entspricht direkt Position n an Ende B. Wird mit einem intern gedrehten Stecker gefertigt, um die Reihenumkehr auszugleichen.",
    "polarity_desc_C": "Kabel mit vertauschten Nachbarpaaren. Key-up an Ende A, Key-down an Ende B. Aufeinanderfolgende Faserpaare werden vor dem Drehen des Endsteckers transponiert — verwendet, wenn Kassettenmodule eine Paar-Neuzuordnung erfordern.",
