    "phase_slow_start": "Slow-Start",
    "phase_ca": "Stauvermeidung",
    "phase_fast_recovery": "Schnelle Wiederherstellung",
    "sysctl_title": "Linux-TCP-Tuning (sysctl)",
    "sysctl_subtitle": "sysctl-Befehle erzeugen, um Linux-TCP-Puffer und Congestion Control auf Ihre Pfadparameter abzustimmen.",
    "sysctl_algo": "Congestion-Control-Algorithmus",
    "sysctl_apply_hint": "Anwenden mit: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Die Werte werden aus Ihrem BDP berechnet.",
    "ref_title": "Algorithmusreferenz",
    "ref_reno_desc": "Klassischer AIMD-Algorithmus. Slow Start verdoppelt cwnd pro RTT bis ssthresh. Stauvermeidung fügt ~1 Segment pro RTT hinzu. Bei 3 doppelten ACKs: ssthresh = cwnd/2, cwnd = ssthresh. Bei Timeout: cwnd = 1 MSS. Fair, nutzt aber nach Verlusten Pfade mit hohem BDP unteraus.",
    "ref_cubic_desc": "Standard in Linux. Verwendet eine kubische Funktion W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7). Nach einem Verlust fällt cwnd auf 70 % von W_max und wächst dann über die konkav-konvexe Kurve. Aggressiver als Reno in Long-Fat-Netzen. K = (W_max * 0.3 / C)^(1/3).",
    "ref_bbr_desc": "Googles modellbasierter Algorithmus. Schätzt Engpass-Bandbreite und minimale RTT, statt Verluste als Signal zu nutzen. Phasen: Startup (Faktor 2.89x), Drain, ProbeBW (8-phasiger Gewinnzyklus: 1.25/0.75/1...), ProbeRTT (4 Segmente alle ~10 s). Erreicht vollen Durchsatz auch bei Verlusten.",
    "phase_startup": "Startup",
    "phase_drain": "Drain",
    "phase_probe_bw": "ProbeBW",
    "phase_probe_rtt": "ProbeRTT",
