    "plat_iosxr_notes": "IOS-XR-Dateisysteme verwenden disk0: oder disk1: statt flash:. SCP-/SFTP-Befehle in XR fragen das Benutzerkennwort interaktiv ab. Der Routing-Kontext (VRF) kann global konfiguriert werden.",
    "plat_nxos_notes": "NX-OS verwendet standardmäßig bootflash:. Prüfen Sie den Speicherplatz mit \"dir bootflash:\". Das VRF muss IP-Erreichbarkeit zum Server haben; prüfen Sie das Default-Routing oder das Management-VRF.",
    "plat_junos_notes": "Kopierte Dateien liegen auf Junos unter /var/tmp/ oder /var/db/config/. Prüfen Sie den Speicherplatz mit \"show system storage\". TFTP-Übertragungen erfordern ggf. Routing-Protokoll-Konfigurationen in Junos oder die Verwendung des Schlüsselworts routing-instance.",
    "plat_eos_notes": "Arista-Geräte verwenden flash:. Prüfen Sie dies mit \"dir flash:\". Für hohen Durchsatz unterstützt Arista native HTTP-/HTTPS-Kopien, die stark optimiert sind.",
    "plat_fortios_notes": "Der TFTP-Restore in FortiOS ersetzt das Boot-Image und startet das Gerät automatisch neu. Mit Vorsicht verwenden. Speichern Sie vorher immer die Konfigurationsdateien.",
    "plat_panos_notes": "Palo Alto PAN-OS erfordert explizite CLI-Administratorrechte, um Software-Import-Befehle auszuführen. Die Software kann auch direkt über die offiziellen Palo-Alto-Support-Updates heruntergeladen werden.",
    "plat_linux_notes": "Prüfen Sie die Lese-/Schreibrechte des Zielverzeichnisses. Stellen Sie sicher, dass der Client (scp, curl) installiert ist. HTTP-/HTTPS-Übertragungen mit curl/wget lassen sich hervorragend parallelisieren.",
    "plat_f5_notes": "Prüfen Sie die bigstart-Prozesse und die administrativen Routen-Berechtigungen der F5. Der Zielordner /shared/images/ ist der Standardspeicherort für F5-ISO-Dateien.",
