    "cap_desc_star": "Star Topologie: Alle Geräte verbinden sich direkt mit dem Koordinator. Einfach und niedrige Latenz, aber auf einen Hop begrenzt. Maximale Geräteanzahl entspricht der Child-Kapazität des Koordinators (Cm).",
