    "cap_desc_mesh": "Mesh Topologie: Router leiten den Datenverkehr für andere Nodes weiter und ermöglichen selbstheilende Pfade. Der Adressraum umfasst den vollen 16-bit Bereich (0x0000–0xFFFF). Die praktischen Grenzen hängen von der Größe der Routing-Tabelle und der Verkehrslast ab.",
