    "pat_sizing_title": "PAT-Kapazitäts- & Dimensionsplaner",
    "tab_flow_table": "Übersetzungs-Ablauftabelle",
    "tab_device_configs": "Gerätekonfiguration",
    "tab_dual_scenarios": "Doppel-NAT-Szenarien",
    "pat_strategy_label": "Port-Zuteilungsstrategie",
    "strategy_dynamic": "Dynamisch bei Bedarf (Standard-PAT)",
    "strategy_deterministic": "Deterministische Block-Zuteilung (CGNAT)",
    "est_ports_per_sub": "Spitzen-Ports je Teilnehmer (geschätzt)",
    "block_size_cgnat": "CGNAT-Port-Blockgröße (reserviert)",
    "sessions_per_host": "Sitzungen je Host",
    "sessions_per_host_hint": "Gleichzeitige Verbindungen, die jeder interne Host öffnet. Benötigte Ports gesamt = Hosts × Sitzungen.",
    "desc_strategy_dynamic": "Standard-PAT vergibt Quellports dynamisch einzeln, sobald Verbindungen aufgebaut werden. Der Wert hier repräsentiert die modellierte Spitzen-Portnutzung je Host zur Schätzung der Gesamtkapazität.",
    "desc_strategy_deterministic": "CGNAT reserviert jedem Teilnehmer vorab einen festen Block von Quellports. Das garantiert Portverfügbarkeit und reduziert den Syslog-Aufwand um 99 % (nur die Block-Zuteilung wird geloggt, nicht jede Sitzung), begrenzt aber die Teilnehmerzahl je öffentlicher IP.",
    "sim_scaled_pool_note": "*Simulation eines verkleinerten Pools mit {total} Ports ({perIp} Ports/IP), um die Erschöpfung sichtbar zu machen, ohne tausende Zeilen zu rendern.",
