    "scenario_overlap_title": "Szenario 1: Überlappende Subnetze (IPsec-VPN)",
    "scenario_overlap_desc": "Zwei Netze nutzen denselben privaten Bereich (z. B. 192.168.1.0/24). Um ohne IP-Konflikte zu kommunizieren, müssen beide Seiten NAT betreiben. Host A wird auf eine Transit-IP übersetzt, und Host B wird auf eine Transit-IP übersetzt.",
    "scenario_cgnat_title": "Szenario 2: Carrier-Grade NAT (CGNAT) zu Kunden-NAT",
    "scenario_cgnat_desc": "Der Provider weist dem Kunden-WAN 100.64.0.0/10 (RFC 6598) zu. Der Kunde betreibt lokales NAT (192.168.1.0/24 -> 100.64.1.2), und der Provider führt CGNAT durch (100.64.1.2 -> öffentliche IP), um IPv4-Adressraum zu sparen.",
