    "err_invalid_ip": "Ungültiges IP-Adressformat",
    "explanation_title": "NAT vs. PAT verstehen",
    "explanation_intro": "Network Address Translation (NAT) und Port Address Translation (PAT) sind Techniken, um einen IP-Adressraum auf einen anderen abzubilden — primär, um den knappen öffentlichen IPv4-Adressraum zu schonen oder Subnetz-Konflikte aufzulösen.",
    "nat_expl_title": "1. Was ist NAT?",
    "nat_expl_desc": "NAT übersetzt IP-Adressen im 1:1-Verfahren. Es kann statisch sein (permanente Zuordnung einer privaten IP zu einer öffentlichen IP — ideal für öffentlich erreichbare Server) oder dynamisch (weist bei Bedarf eine öffentliche IP aus einem Pool an einen privaten Host zu. Sind alle öffentlichen IPs vergeben, werden weitere Hosts blockiert, bis eine IP freigegeben wird). Portnummern bleiben unverändert.",
    "pat_expl_title": "2. Was ist PAT (NAT Overload)?",
    "pat_expl_desc": "PAT (Port Address Translation / NAT Overload) übersetzt sowohl die IP-Adresse als auch die Quellportnummer im N-zu-1-Verfahren. Mehrere private Hosts teilen sich eine einzige öffentliche IP-Adresse über eindeutige Quellports (z. B. werden 192.168.1.10:5000 und 192.168.1.11:5000 auf 203.0.113.10:1024 und 203.0.113.10:1025 abgebildet). Dies ist die Standardmethode bei Heimroutern und Unternehmens-Internetzugängen.",
    "comparison_table_title": "Vergleichsübersicht",
    "comp_header_feature": "Funktion",
    "comp_header_nat": "NAT (1-to-1)",
    "comp_header_pat": "PAT (N:1 / Overload)",
