    "about_body": "iperf ist ein aktives Messwerkzeug für die maximal erreichbare Bandbreite in IP-Netzwerken. Ein Host läuft als Server (Listener) und ein anderer verbindet sich als Client, um Verkehr über TCP, UDP oder SCTP zu senden (oder zu empfangen) und Durchsatz, Jitter sowie Paketverlust zu melden. iperf3 (Binärdatei iperf3) ist eine moderne Neuentwicklung mit JSON-Ausgabe und Reverse/Bidirektional-Modi; iperf2 (Binärdatei iperf) unterstützt mehrere Clients und ist stärker bei Wi-Fi und Multicast. Die beiden Versionen sind NICHT zueinander kompatibel — beide Enden müssen dieselbe Version nutzen.",
