    "note_1": "iperf3 kann nur einen Client gleichzeitig verarbeiten; führen Sie mehrere iperf3-Instanzen auf verschiedenen Ports für gleichzeitige Tests aus.",
    "note_2": "Steuer- und Datenverkehr nutzen denselben Port (Standard 5201 für iperf3, 5001 für iperf2) — öffnen Sie sowohl TCP als auch UDP auf diesem Port in Ihrer Firewall.",
